import fs from 'node:fs/promises';import crypto from 'node:crypto';import path from 'node:path';
const root=path.dirname(decodeURIComponent(new URL(import.meta.url).pathname).replace(/^\/(\w:)/,'$1'));
const srcDir='D:/Dropbox/Claude Projects/Personal Development/CV 2025/',sourcePath=srcDir+'Ahmed El Gendy — Career & Systems Hub.html',source=await fs.readFile(sourcePath,'utf8');
function literal(name){let start=source.search(new RegExp('(?:const|var|let) '+name+'\\s*=')),pos=source.indexOf('=',start)+1;while(/\s/.test(source[pos]))pos++;let quote=false,escape=false,depth=0,end=pos;for(;end<source.length;end++){let c=source[end];if(quote){if(escape)escape=false;else if(c==='\\')escape=true;else if(c==='"')quote=false;}else if(c==='"')quote=true;else if(c==='['||c==='{')depth++;else if(c===']'||c==='}'){if(--depth===0)break;}}return JSON.parse(source.slice(pos,end+1));}
const data=JSON.parse(source.match(/<script id="data" type="application\/json">([\s\S]*?)<\/script>/)[1]);
const imported={skills:literal('RESID'),resources:literal('RESBOARD'),systems:literal('BLUEPRINTS'),agents:literal('AGENTS'),docs:data.docs.filter(x=>/AI Agent/.test(x.section)),assets:{}},audit=[];
const paths=[...new Set([...Object.values(imported.skills).flat().filter(x=>x.p).map(x=>'11 Resources/'+x.p),...imported.systems.flatMap(x=>[x.file,x.map]).filter(Boolean),...imported.docs.map(x=>x.path)])];
for(const rel of paths){try{const bytes=await fs.readFile(srcDir+rel),ext=rel.split('.').pop().toLowerCase();imported.assets[rel]={size:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),...(['md','txt','html','json','js','css','py','yaml','yml'].includes(ext)?{text:bytes.toString('utf8')}:{base64:bytes.toString('base64')})};audit.push({path:rel,status:'copied',bytes:bytes.length});}catch(e){audit.push({path:rel,status:'missing',reason:e.code});}}
const privateDir=path.resolve(root,'../../../private-source-review');await fs.mkdir(privateDir,{recursive:true});await fs.writeFile(path.join(privateDir,'source-data.json'),JSON.stringify(imported));await fs.writeFile(path.join(privateDir,'source-original.html'),source);const selectedPaths=new Set([...imported.skills.skills.map(x=>'11 Resources/'+x.p),...imported.systems.flatMap(x=>[x.file,x.map])]);const selected={skills:{skills:imported.skills.skills,mcps:imported.skills.mcps},resources:imported.resources,systems:imported.systems,agents:[],docs:[],assets:Object.fromEntries(Object.entries(imported.assets).filter(([key])=>selectedPaths.has(key)))};await fs.writeFile(path.join(root,'selected-sections.json'),JSON.stringify(selected));
await fs.writeFile(path.join(root,'audit.json'),JSON.stringify({source:sourcePath,sourceHash:crypto.createHash('sha256').update(source).digest('hex'),counts:{skills:imported.skills.skills.length,mcps:imported.skills.mcps.length,systems:imported.systems.length,agents:imported.agents.length,resources:imported.resources.reduce((n,c)=>n+c.items.length,0)},files:audit},null,2));
console.log(JSON.stringify({found:audit.filter(x=>x.status==='copied').length,missing:audit.filter(x=>x.status==='missing'),bytes:Buffer.byteLength(JSON.stringify(imported))}));
